('81000000-0000-4000-8000-000000000002','pn-acs-change-escalation','active',1),
('81000000-0000-4000-8000-000000000003','rn-dysrhythmia-unstable-priority','active',1),
('81000000-0000-4000-8000-000000000004','pn-dysrhythmia-focused-response','active',1),
('81000000-0000-4000-8000-000000000005','rn-hypertension-teaching-evaluation','active',1),
