insert into public.question_versions(id,question_id,version,stem,item_type,exam_tracks,subject,topic,client_need,clinical_judgment_step,difficulty,rationale_correct,rationale_distractors,memory_rule,source_note,validation_status,professional_role_focus,track_rationale) values
('82000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001',1,'The RN is assessing a client with new substernal chest pressure, diaphoresis, and nausea. Which action should the RN prioritize?','single_best_answer',array['rn'],'Adult Health: Cardiovascular','Acute Coronary Syndrome','Physiological Integrity','Take Action','medium','Treat the presentation as a time-sensitive possible acute coronary syndrome. The RN should rapidly assess the client, obtain vital signs and focused cardiovascular data, and activate the facility chest-pain/ACS process so diagnostic evaluation and prescribed treatment are not delayed.','Routine teaching, waiting to see whether symptoms resolve, or focusing first on nonurgent history delays evaluation of a potentially life-threatening change.','RN: new ischemic symptoms are time-sensitive — assess rapidly and activate the appropriate response pathway.','Original NursePrepIQ pilot item; align final publication with current facility-independent ACS standards and 2026 NCLEX-RN test plan. Not an NCSBN item.','pilot','RN rapid comprehensive assessment, prioritization, and coordination of care for a potentially unstable cardiovascular presentation.','RN-specific because the decision centers on prioritizing assessment and coordinating the immediate nursing response to a potentially unstable presentation.'),
('82000000-0000-4000-8000-000000000002','81000000-0000-4000-8000-000000000002',1,'The LPN/VN is caring for a client who suddenly reports substernal chest pressure with sweating and nausea. What is the priority action?','single_best_answer',array['pn'],'Adult Health: Cardiovascular','Acute Coronary Syndrome','Physiological Integrity','Take Action','medium','The LPN/VN should recognize the acute change, remain with the client, obtain focused data such as vital signs as appropriate, maintain safety, and promptly notify/activate the appropriate RN or emergency response according to the setting and established plan.','Delaying communication for routine documentation, teaching, or waiting for symptoms to resolve can postpone evaluation of a potentially serious change.','PN: recognize the change, collect focused data, keep the client safe, and escalate promptly.','Original NursePrepIQ pilot item; align final publication with current facility-independent ACS standards and 2026 NCLEX-PN test plan. Not an NCSBN item.','pilot','PN recognition of acute change, focused data collection, safety, and prompt communication/escalation.','PN-specific because the decision tests recognition and escalation of an acute change while working within the practical/vocational nurse role.'),
('82000000-0000-4000-8000-000000000003','81000000-0000-4000-8000-000000000003',1,'The RN notes a new rapid irregular rhythm on the monitor. The client is pale, confused, and hypotensive. Which finding most strongly determines the RN priority?','single_best_answer',array['rn'],'Adult Health: Cardiovascular','Dysrhythmias','Physiological Integrity','Analyze Cues','medium','Confusion and hypotension indicate impaired perfusion and hemodynamic instability. The RN should prioritize the client response and rapidly coordinate appropriate assessment and intervention rather than focusing on the monitor pattern alone.','A rhythm label, chronic history, or an isolated monitor rate is less important than evidence that circulation and organ perfusion are compromised.','RN: treat the client, not just the monitor — instability is defined by the client response.','Original NursePrepIQ pilot item aligned to clinical judgment and cardiovascular perfusion. Not an NCSBN item.','pilot','RN synthesis of rhythm data with hemodynamic assessment to identify instability and prioritize care.','RN-specific because the learner must synthesize monitor information with whole-client perfusion findings and prioritize management.'),
('82000000-0000-4000-8000-000000000004','81000000-0000-4000-8000-000000000004',1,'The LPN/VN observes that a client with a known dysrhythmia is newly dizzy and has a blood pressure well below the documented baseline. What should the LPN/VN do first?','single_best_answer',array['pn'],'Adult Health: Cardiovascular','Dysrhythmias','Physiological Integrity','Recognize Cues','medium','New dizziness with a significant blood-pressure decrease may indicate reduced perfusion. The LPN/VN should assess focused findings within scope, protect the client from injury, and promptly communicate the change according to the established plan and care setting.','Routine teaching, postponing reassessment, or assuming the finding is expected because the dysrhythmia is known can miss deterioration.','PN: a known diagnosis does not make a new change normal — reassess, protect, report.','Original NursePrepIQ pilot item aligned to 2026 NCLEX-PN monitoring and clinical judgment. Not an NCSBN item.','pilot','PN monitoring for change, focused data collection, fall/safety protection, and prompt communication.','PN-specific because the decision centers on detecting a change in a client with an established condition and escalating it appropriately.'),
('82000000-0000-4000-8000-000000000005','81000000-0000-4000-8000-000000000005',1,'After teaching a client with hypertension about long-term management, which statement should the RN identify as requiring further teaching?','single_best_answer',array['rn'],'Adult Health: Cardiovascular','Hypertension','Health Promotion and Maintenance','Evaluate Outcomes','easy','A statement that prescribed antihypertensive medication can be stopped whenever the blood pressure is normal requires correction. A normal reading may reflect effective treatment; medication changes should follow the prescribed plan and clinician guidance.','Adherence to the treatment plan, follow-up monitoring, and lifestyle measures are appropriate components of long-term blood-pressure management.','RN teaching evaluation: controlled does not automatically mean cured; evaluate understanding before discharge.','Original NursePrepIQ pilot item. Medication decisions remain individualized and prescriber-directed. Not an NCSBN item.','pilot','RN planning and evaluation of client education for chronic disease self-management.','RN-specific because the learner evaluates whether the teaching plan produced adequate understanding and identifies a remaining learning need.'),
('82000000-0000-4000-8000-000000000006','81000000-0000-4000-8000-000000000006',1,'The LPN/VN is reinforcing previously established teaching for a client with hypertension. Which client statement should the LPN/VN report as evidence that more teaching is needed?','single_best_answer',array['pn'],'Adult Health: Cardiovascular','Hypertension','Health Promotion and Maintenance','Evaluate Outcomes','easy','The client who plans to stop prescribed blood-pressure medication whenever readings are normal demonstrates misunderstanding. The LPN/VN should reinforce the established teaching and communicate the learning need according to the plan of care.','Following prescribed monitoring, medication, and lifestyle recommendations is consistent with established hypertension teaching.','PN teaching: reinforce the established plan and report misunderstanding or barriers.','Original NursePrepIQ pilot item. Medication decisions remain individualized and prescriber-directed. Not an NCSBN item.','pilot','PN reinforcement of established teaching and recognition/reporting of an unmet learning need.','PN-specific because the teaching decision is framed as reinforcement of an established plan rather than independent development of the overall education plan.'),
('82000000-0000-4000-8000-000000000007','81000000-0000-4000-8000-000000000007',1,'The RN assesses a client with peripheral arterial disease. Which new finding requires the highest priority follow-up?','single_best_answer',array['rn'],'Adult Health: Cardiovascular','Peripheral Vascular Disease','Physiological Integrity','Prioritize Hypotheses','medium','A newly cold, pale extremity with markedly diminished pulses suggests an acute reduction in arterial perfusion and requires urgent assessment and escalation.','Chronic exertional discomfort and established skin changes are important but do not carry the same implication of sudden threatened perfusion.','RN: sudden loss of perfusion outranks chronic vascular findings.','Original NursePrepIQ pilot item aligned to cardiovascular perfusion and 2026 NCLEX-RN clinical judgment. Not an NCSBN item.','pilot','RN comprehensive neurovascular assessment and prioritization of an acute perfusion threat.','RN-specific because the learner must distinguish chronic vascular findings from an acute perfusion emergency and prioritize comprehensive assessment/escalation.'),
('82000000-0000-4000-8000-000000000008','81000000-0000-4000-8000-000000000008',1,'The LPN/VN caring for a client with peripheral arterial disease notes that one foot is suddenly colder and paler than earlier and the pulse is more difficult to detect. What is the priority response?','single_best_answer',array['pn'],'Adult Health: Cardiovascular','Peripheral Vascular Disease','Physiological Integrity','Recognize Cues','medium','The LPN/VN should recognize this as a significant change in perfusion, perform focused neurovascular data collection within scope, protect the extremity, and promptly communicate/escalate the finding according to the setting.','Waiting for the next scheduled assessment or treating the change as an expected chronic finding can delay evaluation of worsening arterial perfusion.','PN: compare with baseline — sudden perfusion change requires focused assessment and prompt reporting.','Original NursePrepIQ pilot item aligned to monitoring and recognition of change. Not an NCSBN item.','pilot','PN comparison with baseline, focused neurovascular data collection, safety, and prompt reporting of deterioration.','PN-specific because the item tests monitoring an established condition and recognizing when a new finding requires escalation.')
insert into public.question_options(question_version_id,option_key,option_text,is_correct,rationale,display_order) values
('82000000-0000-4000-8000-000000000001','a','Complete routine discharge teaching before reassessing the symptoms.',false,'Teaching should not delay evaluation of acute ischemic symptoms.',1),('82000000-0000-4000-8000-000000000001','b','Rapidly assess the client and activate the facility chest-pain/ACS process.',true,'This prioritizes timely assessment and coordination for a potentially unstable presentation.',2),('82000000-0000-4000-8000-000000000001','c','Wait to determine whether the pressure resolves without intervention.',false,'Waiting may delay evaluation of a time-sensitive condition.',3),('82000000-0000-4000-8000-000000000001','d','Focus first on obtaining a complete dietary history.',false,'A dietary history is not the priority during acute symptoms.',4),
('82000000-0000-4000-8000-000000000002','a','Wait 30 minutes to see whether the symptoms resolve.',false,'Waiting delays evaluation of an acute change.',1),('82000000-0000-4000-8000-000000000002','b','Finish routine documentation before notifying anyone.',false,'Documentation should not delay urgent communication.',2),('82000000-0000-4000-8000-000000000002','c','Stay with the client, obtain focused data, maintain safety, and promptly escalate according to the setting.',true,'This matches PN recognition, monitoring, safety, and communication responsibilities.',3),('82000000-0000-4000-8000-000000000002','d','Begin routine diet teaching to reduce the client’s anxiety.',false,'Routine teaching is not the priority during acute symptoms.',4),
('82000000-0000-4000-8000-000000000003','a','The rhythm is irregular.',false,'Irregularity matters, but the client’s perfusion determines urgency.',1),('82000000-0000-4000-8000-000000000003','b','The client is confused and hypotensive.',true,'These findings indicate impaired perfusion and instability.',2),('82000000-0000-4000-8000-000000000003','c','The client has a history of hypertension.',false,'History does not establish current hemodynamic stability.',3),('82000000-0000-4000-8000-000000000003','d','The monitor rate is faster than the client’s usual rate.',false,'Rate alone is less important than evidence of compromised perfusion.',4),
('82000000-0000-4000-8000-000000000004','a','Assume the symptoms are expected because the dysrhythmia is already diagnosed.',false,'A new change still requires assessment and communication.',1),('82000000-0000-4000-8000-000000000004','b','Encourage the client to walk to determine whether dizziness improves.',false,'Ambulation increases fall risk in a dizzy, hypotensive client.',2),('82000000-0000-4000-8000-000000000004','c','Collect focused data, protect the client from injury, and promptly report the change.',true,'This addresses monitoring, safety, and escalation.',3),('82000000-0000-4000-8000-000000000004','d','Delay reassessment until the next scheduled vital-sign check.',false,'New hypotension and dizziness warrant prompt attention.',4),
('82000000-0000-4000-8000-000000000005','a','I will keep my follow-up appointments even when I feel well.',false,'Ongoing follow-up is appropriate.',1),('82000000-0000-4000-8000-000000000005','b','If my blood pressure becomes normal, I can stop my prescribed medication on my own.',true,'This reflects unsafe misunderstanding of long-term management.',2),('82000000-0000-4000-8000-000000000005','c','I will follow the monitoring plan my health care team recommends.',false,'Following the monitoring plan is appropriate.',3),('82000000-0000-4000-8000-000000000005','d','Lifestyle changes remain important even when medication is prescribed.',false,'Lifestyle measures can remain part of the management plan.',4),
('82000000-0000-4000-8000-000000000006','a','I should follow the blood-pressure monitoring plan I was given.',false,'This demonstrates understanding.',1),('82000000-0000-4000-8000-000000000006','b','I can stop my prescribed medication whenever my blood pressure is normal.',true,'This indicates a need for reinforced teaching and communication of the learning need.',2),('82000000-0000-4000-8000-000000000006','c','I will keep follow-up appointments even if I have no symptoms.',false,'This demonstrates appropriate understanding.',3),('82000000-0000-4000-8000-000000000006','d','I will continue the lifestyle changes included in my care plan.',false,'This is consistent with the established plan.',4),
('82000000-0000-4000-8000-000000000007','a','Leg discomfort that predictably occurs with walking and resolves with rest.',false,'This can reflect a chronic pattern rather than sudden deterioration.',1),('82000000-0000-4000-8000-000000000007','b','A newly cold, pale foot with markedly diminished pulses.',true,'This suggests an acute reduction in arterial perfusion.',2),('82000000-0000-4000-8000-000000000007','c','Chronic decreased hair growth on the lower leg.',false,'This is a chronic arterial insufficiency finding.',3),('82000000-0000-4000-8000-000000000007','d','A longstanding history of smoking.',false,'This is an important risk factor but not the most urgent current finding.',4),
('82000000-0000-4000-8000-000000000008','a','Document the finding and wait until the next scheduled assessment.',false,'A sudden perfusion change should not be deferred.',1),('82000000-0000-4000-8000-000000000008','b','Apply direct heat to the foot.',false,'Direct heat can injure tissue with impaired perfusion and does not address the acute change.',2),('82000000-0000-4000-8000-000000000008','c','Perform focused neurovascular data collection and promptly report/escalate the change.',true,'This addresses recognition, monitoring, safety, and communication.',3),('82000000-0000-4000-8000-000000000008','d','Encourage vigorous walking before reassessing the foot.',false,'Exercise is inappropriate when there is a sudden possible perfusion compromise.',4)
